<?php
/**
 * Builds wizard/templates.js from the scaffold sources, so the web wizard
 * generates exactly what `composer create-project` does.
 *
 * Run from the repository root: php scripts/build-wizard-templates.php
 * The GitHub Pages workflow runs it before publishing the wizard; the file is
 * not committed.
 */

$root = dirname( __DIR__ );

require_once $root . '/src/Scaffolder.php';

use Akirk\CreateWpApp\Scaffolder;

$read = static function ( string $file ) use ( $root ): string {
    $contents = file_get_contents( $root . '/' . $file );
    if ( $contents === false ) {
        fwrite( STDERR, "Missing $file\n" );
        exit( 1 );
    }
    return $contents;
};

// composer.json of a generated app starts from this repository's, minus what
// ComposerJsonFactory replaces or removes.
$composer = json_decode( $read( 'composer.json' ), true );
unset( $composer['name'], $composer['description'], $composer['autoload'], $composer['archive'], $composer['scripts'] );

$templates = [
    'baseComposer' => $composer,
    'mainPluginTemplate' => $read( 'plugin-name.php' ),
    'fullSetupCode' => Scaffolder::setup_code_template( true ),
    'minimalSetupCode' => Scaffolder::setup_code_template( false ),
    'appTemplate' => $read( 'src/App.php' ),
    'templateTemplate' => $read( 'templates/index.php' ),
    'readmeTemplate' => Scaffolder::readme_template(),
    'gitignoreTemplate' => Scaffolder::gitignore_template(),
    'autoloadPolyfill' => Scaffolder::snippet( 'autoload-polyfill.php' ),
];

$output = "// Generated by scripts/build-wizard-templates.php from the scaffold sources\n"
    . "// (plugin-name.php, src/App.php, templates/index.php, .create-wp-app/). Do not\n"
    . "// edit: change those files instead. The assigned value is plain JSON.\n"
    . 'window.CreateWpAppTemplates = ' . json_encode( $templates, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES ) . ";\n";

file_put_contents( $root . '/wizard/templates.js', $output );
echo "Wrote wizard/templates.js\n";
